insert into public.destinations (id, slug, name, country, region, short_description, description, image_url, attractions, travel_info, is_popular) values
  ('34b1c4d1-afc7-5cc7-a1ff-a5169c476925', 'goa', 'Goa', 'India', 'India', 'Golden beaches, Portuguese heritage and laid-back coastal living.', 'Goa blends palm-fringed beaches with whitewashed churches, spice plantations and a famously relaxed pace. Spend mornings on quiet southern sands, afternoons exploring Old Goa''s baroque architecture and evenings at beach shacks serving fresh seafood as the sun sets over the Arabian Sea.', 'https://images.unsplash.com/photo-1512343879784-a960bf40e7f2?auto=format&fit=crop&w=1600&q=80', '[{"name":"Palolem Beach","description":"A crescent bay with calm water, kayaking and beach huts."},{"name":"Basilica of Bom Jesus","description":"UNESCO-listed 16th-century church in Old Goa."},{"name":"Fontainhas","description":"Colourful Latin Quarter of Panaji with Portuguese villas."},{"name":"Dudhsagar Falls","description":"Four-tiered waterfall deep in the Western Ghats."}]'::jsonb, '{"bestTimeToVisit":"November to February","currency":"Indian Rupee (INR)","language":"Konkani, English, Hindi","timezone":"IST (UTC+5:30)","gettingThere":"Fly into Goa (GOI) or Mopa (GOX) airport, or take the Konkan Railway."}'::jsonb, true),
  ('51e8e26c-f07e-5f7a-a269-bcc7e5828c26', 'jaipur', 'Jaipur', 'India', 'India', 'The Pink City of palaces, forts and vibrant bazaars.', 'Rajasthan''s capital is a feast of royal architecture and colour. Wander through the honeycomb façade of the Hawa Mahal, climb the ramparts of Amber Fort and shop for block-printed textiles and gemstones in the old city''s bustling bazaars.', 'https://images.unsplash.com/photo-1477587458883-47145ed94245?auto=format&fit=crop&w=1600&q=80', '[{"name":"Amber Fort","description":"Hilltop fort with mirrored halls and sweeping views."},{"name":"Hawa Mahal","description":"The iconic ''Palace of Winds'' with 953 latticed windows."},{"name":"City Palace","description":"Royal residence and museum in the heart of the old city."},{"name":"Jantar Mantar","description":"18th-century astronomical observatory, UNESCO listed."}]'::jsonb, '{"bestTimeToVisit":"October to March","currency":"Indian Rupee (INR)","language":"Hindi, Rajasthani, English","timezone":"IST (UTC+5:30)","gettingThere":"Jaipur International Airport (JAI) or a 4.5-hour train from Delhi."}'::jsonb, true),
  ('8b59ee54-55de-51f2-ba0b-c15d56f0ee9c', 'kerala', 'Kerala', 'India', 'India', 'Tranquil backwaters, tea-covered hills and Ayurvedic retreats.', 'Known as God''s Own Country, Kerala offers houseboat cruises through palm-lined backwaters, misty tea estates in Munnar and wellness retreats rooted in centuries of Ayurvedic tradition. The cuisine — coconut, curry leaves and fresh catch — is reason enough to visit.', 'https://images.unsplash.com/photo-1602216056096-3b40cc0c9944?auto=format&fit=crop&w=1600&q=80', '[{"name":"Alleppey Backwaters","description":"Overnight houseboat cruises through village canals."},{"name":"Munnar Tea Gardens","description":"Rolling green hills and tea-tasting tours."},{"name":"Fort Kochi","description":"Chinese fishing nets, spice markets and art cafés."},{"name":"Periyar Wildlife Sanctuary","description":"Elephants, bamboo rafting and spice walks."}]'::jsonb, '{"bestTimeToVisit":"September to March","currency":"Indian Rupee (INR)","language":"Malayalam, English","timezone":"IST (UTC+5:30)","gettingThere":"Fly into Kochi (COK) or Thiruvananthapuram (TRV)."}'::jsonb, true),
  ('76df4470-0b3e-5872-ac0e-2e548da9319d', 'manali', 'Manali', 'India', 'India', 'Snow-capped Himalayan peaks, pine forests and adventure.', 'Set in the Kullu Valley, Manali is a gateway to the high Himalaya. Summer brings trekking, paragliding and river rafting; winter covers the slopes of Solang Valley in snow. Old Manali''s cafés and the ancient Hadimba Temple add a slower, cultural side.', 'https://images.unsplash.com/photo-1626621341517-bbf3d9990a23?auto=format&fit=crop&w=1600&q=80', '[{"name":"Solang Valley","description":"Skiing in winter, paragliding and zorbing in summer."},{"name":"Hadimba Devi Temple","description":"Wooden pagoda temple set in a cedar forest."},{"name":"Rohtang Pass","description":"High mountain pass with year-round snow views."},{"name":"Old Manali","description":"Cafés, riverside walks and a backpacker vibe."}]'::jsonb, '{"bestTimeToVisit":"March to June, December to February for snow","currency":"Indian Rupee (INR)","language":"Hindi, Pahari, English","timezone":"IST (UTC+5:30)","gettingThere":"Fly into Bhuntar (KUU) or take an overnight bus from Delhi."}'::jsonb, false),
  ('0f91436a-70d9-54d4-96ea-78b7d1204b3e', 'bali', 'Bali', 'Indonesia', 'Asia', 'Temples, rice terraces and world-class surf beaches.', 'Bali pairs spiritual culture with tropical indulgence. Visit lakeside water temples, walk the emerald rice terraces of Tegallalang, take a yoga class in Ubud and end the day with a sunset dinner on the cliffs of Uluwatu.', 'https://images.unsplash.com/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=1600&q=80', '[{"name":"Ulun Danu Beratan Temple","description":"Iconic water temple on Lake Beratan."},{"name":"Tegallalang Rice Terraces","description":"Sculpted green terraces north of Ubud."},{"name":"Uluwatu","description":"Clifftop temple, surf breaks and Kecak fire dance."},{"name":"Sacred Monkey Forest","description":"Jungle sanctuary home to long-tailed macaques."}]'::jsonb, '{"bestTimeToVisit":"April to October (dry season)","currency":"Indonesian Rupiah (IDR)","language":"Indonesian, Balinese, English","timezone":"WITA (UTC+8)","gettingThere":"Fly into Ngurah Rai International Airport (DPS)."}'::jsonb, true),
  ('41d9be58-f8cc-5ca1-9d76-8130b738b970', 'dubai', 'Dubai', 'United Arab Emirates', 'Middle East', 'Record-breaking skyline, desert safaris and luxury shopping.', 'Dubai is a city of superlatives — the world''s tallest building, vast malls and artificial islands — balanced by the traditional souks of Deira and the quiet of the surrounding desert. Expect year-round sunshine and outstanding hotels at every level.', 'https://images.unsplash.com/photo-1512453979798-5ea266f8880c?auto=format&fit=crop&w=1600&q=80', '[{"name":"Burj Khalifa","description":"Observation decks on the world''s tallest tower."},{"name":"Desert Safari","description":"Dune bashing, camel rides and dinner under the stars."},{"name":"Dubai Marina","description":"Waterfront promenade, dhow cruises and dining."},{"name":"Gold & Spice Souks","description":"Traditional markets along Dubai Creek."}]'::jsonb, '{"bestTimeToVisit":"November to March","currency":"UAE Dirham (AED)","language":"Arabic, English","timezone":"GST (UTC+4)","gettingThere":"Dubai International Airport (DXB), about 3.5 hours from Mumbai."}'::jsonb, true),
  ('a24faba9-a386-5a95-832f-c4ee1bb6b303', 'maldives', 'Maldives', 'Maldives', 'Indian Ocean', 'Overwater villas, turquoise lagoons and coral reefs.', 'Over a thousand coral islands scattered across the Indian Ocean make the Maldives the ultimate island escape. Snorkel with manta rays, dine over the lagoon and fall asleep to the sound of the sea in a villa built on stilts above the water.', 'https://images.unsplash.com/photo-1514282401047-d79a71a590e8?auto=format&fit=crop&w=1600&q=80', '[{"name":"House reefs","description":"World-class snorkelling straight from your villa."},{"name":"Sandbank picnics","description":"Private lunches on deserted sandbanks."},{"name":"Malé","description":"The compact capital with a lively fish market."},{"name":"Bioluminescent beaches","description":"Glowing shorelines on Vaadhoo island."}]'::jsonb, '{"bestTimeToVisit":"November to April","currency":"Maldivian Rufiyaa (MVR), USD widely accepted","language":"Dhivehi, English","timezone":"MVT (UTC+5)","gettingThere":"Fly into Velana International Airport (MLE), then seaplane or speedboat."}'::jsonb, true),
  ('8edebe78-1389-5304-8409-6e8b4b116b5c', 'singapore', 'Singapore', 'Singapore', 'Asia', 'Futuristic gardens, hawker food and a spotless skyline.', 'Singapore packs a lot into a small island: the supertrees of Gardens by the Bay, Michelin-rated hawker stalls, heritage shophouses in Chinatown and Little India, and family attractions on Sentosa — all connected by one of the world''s best metro systems.', 'https://images.unsplash.com/photo-1525625293386-3f8f99389edd?auto=format&fit=crop&w=1600&q=80', '[{"name":"Gardens by the Bay","description":"Supertree Grove and climate-controlled conservatories."},{"name":"Marina Bay Sands","description":"Rooftop SkyPark with views over the bay."},{"name":"Sentosa Island","description":"Beaches, theme parks and an aquarium."},{"name":"Hawker centres","description":"Affordable local food at Maxwell and Lau Pa Sat."}]'::jsonb, '{"bestTimeToVisit":"February to April","currency":"Singapore Dollar (SGD)","language":"English, Mandarin, Malay, Tamil","timezone":"SGT (UTC+8)","gettingThere":"Changi Airport (SIN), with direct flights from major Indian cities."}'::jsonb, false),
  ('d1e45bcf-22b8-5287-bff4-485f99064617', 'santorini', 'Santorini', 'Greece', 'Europe', 'Whitewashed villages perched above a volcanic caldera.', 'Santorini''s cliff-top villages of Oia and Fira overlook a flooded volcanic caldera, making for some of the world''s most famous sunsets. Swim at black-sand beaches, tour volcanic wineries and sail to the hot springs.', 'https://images.unsplash.com/photo-1570077188670-e3a8d69ac5ff?auto=format&fit=crop&w=1600&q=80', '[{"name":"Oia","description":"Blue-domed churches and legendary sunset views."},{"name":"Caldera cruise","description":"Sail to the volcano and natural hot springs."},{"name":"Red Beach","description":"Dramatic red cliffs above a small cove."},{"name":"Akrotiri","description":"Bronze Age city preserved under volcanic ash."}]'::jsonb, '{"bestTimeToVisit":"May to October","currency":"Euro (EUR)","language":"Greek, English","timezone":"EET (UTC+2)","gettingThere":"Fly into Santorini (JTR) or take a ferry from Athens."}'::jsonb, true),
  ('6cf69a3f-f43e-5c59-9cba-b92901af724d', 'paris', 'Paris', 'France', 'Europe', 'Art, cafés and timeless boulevards in the City of Light.', 'Paris rewards both first-time visitors and returning travellers: world-famous museums, riverside walks along the Seine, neighbourhood bistros and grand boulevards that glow at night. Every arrondissement has its own character to discover.', 'https://images.unsplash.com/photo-1502602898657-3e91760cbb34?auto=format&fit=crop&w=1600&q=80', '[{"name":"Eiffel Tower","description":"Iconic iron tower with views across the city."},{"name":"Louvre Museum","description":"Home to the Mona Lisa and 35,000 works of art."},{"name":"Montmartre","description":"Hilltop artists'' quarter crowned by Sacré-Cœur."},{"name":"Seine river cruise","description":"See the landmarks from the water."}]'::jsonb, '{"bestTimeToVisit":"April to June, September to October","currency":"Euro (EUR)","language":"French, English widely spoken","timezone":"CET (UTC+1)","gettingThere":"Charles de Gaulle (CDG) or Orly (ORY) airport."}'::jsonb, false),
  ('1b5a3abc-5cb8-54ec-bd51-195e79975b44', 'london', 'London', 'United Kingdom', 'Europe', 'Royal history, free museums and iconic riverside landmarks.', 'London mixes centuries of history with a constantly changing food, theatre and design scene. Many of its world-class museums are free, its parks are vast and green, and every neighbourhood from Covent Garden to Shoreditch feels like a different city.', 'https://images.unsplash.com/photo-1513635269975-59663e0ac1ad?auto=format&fit=crop&w=1600&q=80', '[{"name":"Tower of London","description":"Medieval fortress and home of the Crown Jewels."},{"name":"British Museum","description":"Free museum of world history and culture."},{"name":"West End theatres","description":"Musicals and plays in theatreland."},{"name":"South Bank","description":"Riverside walk past the London Eye and Tate Modern."}]'::jsonb, '{"bestTimeToVisit":"May to September","currency":"Pound Sterling (GBP)","language":"English","timezone":"GMT (UTC+0)","gettingThere":"Heathrow (LHR), Gatwick (LGW) and other airports."}'::jsonb, false),
  ('9c5dfe4d-f537-5208-a823-ea67766396e5', 'tokyo', 'Tokyo', 'Japan', 'Asia', 'Neon streets, ancient shrines and unforgettable food.', 'Tokyo is a city of contrasts: serene shrines beside neon-lit crossings, centuries-old craft shops next to cutting-edge architecture, and some of the best food on the planet — from tiny ramen counters to Michelin-starred sushi.', 'https://images.unsplash.com/photo-1540959733332-eab4deabeeaf?auto=format&fit=crop&w=1600&q=80', '[{"name":"Shibuya Crossing","description":"The world''s busiest pedestrian scramble."},{"name":"Senso-ji Temple","description":"Tokyo''s oldest temple in historic Asakusa."},{"name":"Shinjuku Gyoen","description":"Landscaped gardens famous for cherry blossoms."},{"name":"Tsukiji Outer Market","description":"Street food, fresh seafood and kitchenware."}]'::jsonb, '{"bestTimeToVisit":"March to May, October to November","currency":"Japanese Yen (JPY)","language":"Japanese","timezone":"JST (UTC+9)","gettingThere":"Haneda (HND) or Narita (NRT) airport."}'::jsonb, false)
