insert into public.hotels (id, slug, destination_id, name, city, address, accommodation_type, star_rating, review_score, review_count, popularity, short_description, description, facilities, check_in_time, check_out_time, cancellation_policy, is_featured, offer_label, offer_discount_percent, is_published) values
  ('e567a4ee-e31a-58f6-a55c-67eddce54cd7', 'palm-shore-beach-resort', '34b1c4d1-afc7-5cc7-a1ff-a5169c476925', 'Palm Shore Beach Resort', 'Cavelossim, South Goa', 'Mobor Beach Road, Cavelossim, Goa 403731', 'resort', 5, 9.1, 1842, 412, 'Beachfront resort with lagoon pools, three restaurants and a full-service spa.', 'Set between the Sal River and a quiet stretch of South Goa coastline, Palm Shore Beach Resort is built around lagoon-style pools shaded by coconut palms. Rooms open onto private balconies, the spa offers Ayurvedic treatments and the beach shack serves the catch of the day at sunset.', array['24-hour front desk', 'Kids'' club', 'Water sports centre', 'Yoga pavilion', 'Laundry service']::text[], '14:00', '11:00', 'Free cancellation up to 48 hours before check-in. Later cancellations are charged one night.', true, 'Early bird', 20, true),
  ('4b935b90-9800-51cc-85a7-8de7a31908ff', 'casa-fontainhas-boutique-hotel', '34b1c4d1-afc7-5cc7-a1ff-a5169c476925', 'Casa Fontainhas Boutique Hotel', 'Panaji, North Goa', '31 de Janeiro Road, Fontainhas, Panaji, Goa 403001', 'boutique', 3, 8.6, 534, 168, 'Restored Portuguese villa in the colourful Latin Quarter of Panaji.', 'A lovingly restored 19th-century Portuguese home with just twelve rooms, Casa Fontainhas puts you in the heart of Panaji''s Latin Quarter. Breakfast is served in a leafy courtyard, and the city''s best cafés, galleries and riverside promenade are a short walk away.', array['Courtyard garden', 'Heritage walking tours', 'Bicycle hire', 'Luggage storage']::text[], '13:00', '11:00', 'Free cancellation up to 48 hours before check-in. Later cancellations are charged one night.', false, null, null, true),
  ('7556deac-bfaf-5934-819e-ab1c230ee31e', 'palm-court-palace-jaipur', '51e8e26c-f07e-5f7a-a269-bcc7e5828c26', 'Palm Court Palace', 'Jaipur', 'Bhawani Singh Road, C-Scheme, Jaipur, Rajasthan 302001', 'hotel', 5, 9.3, 1276, 356, 'Palatial heritage hotel with royal courtyards and a palm-lined pool.', 'Inspired by Rajput palaces, Palm Court Palace pairs carved sandstone arches with contemporary comfort. Evenings bring folk music in the courtyard, the spa draws on traditional rituals and the rooftop restaurant looks out over the Pink City towards Nahargarh Fort.', array['Butler service', 'Cultural evenings', 'Business centre', 'Currency exchange']::text[], '14:00', '12:00', 'Free cancellation up to 7 days before check-in. 50% of the stay is charged after that.', true, null, null, true),
  ('c74482e6-a56e-52cd-b5f7-ab7b94104c4d', 'pink-city-residency', '51e8e26c-f07e-5f7a-a269-bcc7e5828c26', 'Pink City Residency', 'Jaipur', 'MI Road, near Ajmeri Gate, Jaipur, Rajasthan 302001', 'hotel', 3, 7.9, 988, 290, 'Good-value city hotel a short walk from the old city gates.', 'Pink City Residency offers comfortable, practical rooms on MI Road, putting the bazaars, Hawa Mahal and City Palace within walking distance. The rooftop café is a favourite for breakfast with views of the old city walls.', array['Tour desk', '24-hour front desk', 'Rooftop café']::text[], '12:00', '11:00', 'Free cancellation up to 48 hours before check-in. Later cancellations are charged one night.', false, 'Weekend deal', 15, true),
  ('b3fd9a48-d43c-521a-bb5f-f64d4427bb8e', 'backwater-bliss-resort', '8b59ee54-55de-51f2-ba0b-c15d56f0ee9c', 'Backwater Bliss Resort', 'Alleppey', 'Punnamada Lake, Alappuzha, Kerala 688006', 'resort', 4, 9, 712, 244, 'Lakeside cottages, an infinity pool and private houseboat cruises.', 'Spread across a palm-filled island on Punnamada Lake, Backwater Bliss offers traditional Kerala-style cottages with sit-out verandas. Take a sunset canoe ride through village canals, try an Ayurvedic massage or learn to cook a classic fish moilee.', array['Houseboat cruises', 'Ayurveda centre', 'Cooking classes', 'Canoe hire']::text[], '14:00', '11:00', 'Free cancellation up to 7 days before check-in. 50% of the stay is charged after that.', true, 'Monsoon special', 25, true),
  ('a4906aa2-940f-57c9-98c0-4a3e66d33be1', 'munnar-mist-villas', '8b59ee54-55de-51f2-ba0b-c15d56f0ee9c', 'Munnar Mist Villas', 'Munnar', 'Chithirapuram, Munnar, Kerala 685565', 'villa', 4, 8.8, 403, 131, 'Private villas surrounded by tea estates and cloud-covered hills.', 'Each villa at Munnar Mist has its own garden and wide windows framing the tea-covered hills. Join a guided plantation walk at dawn, warm up by the evening bonfire and enjoy home-style Kerala meals made with produce from the estate.', array['Tea plantation tours', 'Bonfire area', 'Children''s play area', 'Trekking guides']::text[], '13:00', '11:00', 'Free cancellation up to 7 days before check-in. 50% of the stay is charged after that.', false, null, null, true),
  ('21033e14-a077-54f7-b4ee-8aeb501c74d9', 'himalayan-pines-retreat', '76df4470-0b3e-5872-ac0e-2e548da9319d', 'Himalayan Pines Retreat', 'Manali', 'Log Huts Area, Manali, Himachal Pradesh 175131', 'resort', 4, 8.7, 621, 203, 'Mountain retreat with valley views, a rooftop deck and fireplace lounges.', 'Tucked into a cedar forest above the Beas River, Himalayan Pines Retreat is a cosy base for Himalayan adventures. Rooms feature warm wood interiors and balconies facing snow-capped peaks; the team can arrange paragliding, treks and ski trips to Solang Valley.', array['Fireplace lounge', 'Adventure desk', 'Rooftop deck', 'Heated rooms']::text[], '13:00', '11:00', 'Free cancellation up to 48 hours before check-in. Later cancellations are charged one night.', false, 'Winter escape', 10, true),
  ('f886d2cc-0136-5ec1-8743-8bb920f185f3', 'uluwatu-cliff-villas', '0f91436a-70d9-54d4-96ea-78b7d1204b3e', 'Uluwatu Cliff Villas', 'Uluwatu', 'Jalan Pantai Suluban, Pecatu, Bali 80361', 'villa', 5, 9.4, 1105, 398, 'Clifftop pool villas above the Indian Ocean with sunset views.', 'Perched on the limestone cliffs of Bali''s Bukit Peninsula, every villa has its own plunge pool facing the ocean. Spend days between the cliff-edge infinity pool and secluded beaches below, then watch the sun sink into the sea from the open-air bar.', array['Private plunge pools', 'Surf lessons', 'Yoga classes', 'In-villa dining']::text[], '15:00', '12:00', 'Non-refundable within 14 days of check-in. Earlier cancellations receive a full refund.', true, null, null, true),
  ('a1c25717-c925-55a5-8278-2eefc1cfd8fa', 'ubud-lotus-resort', '0f91436a-70d9-54d4-96ea-78b7d1204b3e', 'Ubud Lotus Resort', 'Ubud', 'Jalan Raya Sayan, Ubud, Bali 80571', 'resort', 4, 8.9, 867, 276, 'Jungle-view resort near Ubud''s rice terraces and yoga studios.', 'Ubud Lotus Resort sits above the Ayung River valley, surrounded by jungle and rice fields. Start the day with yoga in the open-air pavilion, explore Ubud''s art markets and temples, then unwind with a Balinese massage at the riverside spa.', array['Yoga pavilion', 'Free Ubud shuttle', 'Cooking classes', 'Rice terrace walks']::text[], '14:00', '12:00', 'Free cancellation up to 48 hours before check-in. Later cancellations are charged one night.', false, 'Stay 4, pay 3', 25, true),
  ('61a7ecea-4f2b-5c0f-b6a4-f814b4cf48b5', 'marina-skyline-hotel', '41d9be58-f8cc-5ca1-9d76-8130b738b970', 'Marina Skyline Hotel', 'Dubai Marina', 'King Salman bin Abdulaziz Al Saud Street, Dubai Marina, Dubai', 'hotel', 5, 9, 2310, 455, 'Sleek high-rise hotel with a rooftop pool and marina views.', 'Marina Skyline Hotel rises above Dubai Marina with floor-to-ceiling windows in every room. The rooftop pool glows after dark, the hotel''s beach club is a short shuttle ride away and the Marina Walk''s restaurants are right outside the door.', array['Rooftop pool', 'Beach club access', 'Concierge', 'Valet parking']::text[], '15:00', '12:00', 'Free cancellation up to 7 days before check-in. 50% of the stay is charged after that.', true, null, null, true),
  ('1535db96-56a5-51eb-8a47-dc656f23b06f', 'desert-pearl-resort-spa', '41d9be58-f8cc-5ca1-9d76-8130b738b970', 'Desert Pearl Resort & Spa', 'Al Marmoom, Dubai', 'Al Qudra Road, Al Marmoom Desert, Dubai', 'resort', 5, 8.8, 742, 188, 'Luxury desert resort with pool suites, stargazing and camel treks.', 'An hour from the city, Desert Pearl offers stillness among the dunes. Suites open onto private terraces, dinners are served under the stars and mornings begin with falconry displays or a sunrise camel trek across the sand.', array['Desert activities', 'Stargazing deck', 'Hammam', 'Private dining']::text[], '15:00', '12:00', 'Non-refundable within 14 days of check-in. Earlier cancellations receive a full refund.', false, 'Spa package', 15, true),
  ('402eefdd-2517-500e-abf5-2a0705d9379e', 'coral-lagoon-overwater-villas', 'a24faba9-a386-5a95-832f-c4ee1bb6b303', 'Coral Lagoon Overwater Villas', 'South Malé Atoll', 'Kaafu Atoll, South Malé, Maldives', 'villa', 5, 9.6, 958, 321, 'Overwater villas with glass floors, private decks and reef access.', 'Reached by a 30-minute speedboat ride from Malé, Coral Lagoon''s villas sit on stilts above a turquoise lagoon. Step from your deck straight into the water, snorkel the house reef with turtles and reef sharks, and dine at the underwater restaurant.', array['Dive centre', 'Underwater restaurant', 'Speedboat transfers', 'Sandbank dining']::text[], '14:00', '12:00', 'Non-refundable within 14 days of check-in. Earlier cancellations receive a full refund.', true, 'Honeymoon offer', 20, true),
  ('ed801a1e-b00a-5cca-b901-310d7665b007', 'bayfront-hotel-singapore', '8edebe78-1389-5304-8409-6e8b4b116b5c', 'Bayfront Hotel Singapore', 'Marina Bay', 'Raffles Avenue, Marina Bay, Singapore 039593', 'hotel', 4, 8.5, 1530, 302, 'Waterfront hotel steps from Gardens by the Bay and the MRT.', 'Bayfront Hotel puts you on Singapore''s most famous waterfront, with views across Marina Bay and easy MRT access to Chinatown and Orchard Road. The rooftop bar is perfect for watching the nightly light show.', array['Rooftop bar', 'Self-service laundry', 'Concierge', 'Express check-out']::text[], '15:00', '11:00', 'Free cancellation up to 48 hours before check-in. Later cancellations are charged one night.', false, null, null, true),
  ('99ae36d3-eba2-58ed-9395-34f3333c5957', 'caldera-whites-suites', 'd1e45bcf-22b8-5287-bff4-485f99064617', 'Caldera Whites Suites', 'Oia', 'Main Street, Oia 847 02, Santorini, Greece', 'boutique', 5, 9.5, 689, 254, 'Cave-style suites carved into the caldera cliffs of Oia.', 'Whitewashed cave suites cascade down the cliffside at Caldera Whites, each with a private terrace facing the volcano. Breakfast arrives at your door, the infinity pool looks out to sea and Oia''s famous sunset is visible from every suite.', array['Caldera-view terraces', 'Wine tasting', 'Boat tour bookings', 'Breakfast in suite']::text[], '14:00', '11:00', 'Non-refundable within 14 days of check-in. Earlier cancellations receive a full refund.', true, null, null, true),
  ('88d3aa07-a803-5bef-b1f5-b17fa82fe04c', 'hotel-rive-gauche-paris', '6cf69a3f-f43e-5c59-9cba-b92901af724d', 'Hôtel Rive Gauche', 'Saint-Germain-des-Prés, Paris', 'Rue Jacob, 75006 Paris, France', 'boutique', 4, 8.7, 1122, 233, 'Elegant boutique hotel on the Left Bank near cafés and galleries.', 'Hôtel Rive Gauche brings Parisian elegance to a classic Haussmann building in Saint-Germain. Rooms are styled with velvet and brass, the library bar serves French wines and the Louvre is a ten-minute walk across the Seine.', array['Library bar', 'Concierge', 'Luggage storage', 'Daily housekeeping']::text[], '15:00', '11:00', 'Free cancellation up to 7 days before check-in. 50% of the stay is charged after that.', false, null, null, true),
  ('314eee3d-d591-5986-acaa-4e65304f729e', 'thames-view-apartments', '1b5a3abc-5cb8-54ec-bd51-195e79975b44', 'Thames View Apartments', 'South Bank, London', 'Upper Ground, London SE1 9PP, United Kingdom', 'apartment', 4, 8.4, 876, 197, 'Serviced apartments with kitchens and river views on the South Bank.', 'Thames View offers spacious serviced apartments with fully equipped kitchens — ideal for families and longer stays. Walk along the river to the London Eye, Tate Modern and Borough Market, or hop on the Tube at Waterloo.', array['Fully equipped kitchens', 'Washer-dryer', 'Weekly housekeeping', '24-hour reception']::text[], '15:00', '10:00', 'Free cancellation up to 48 hours before check-in. Later cancellations are charged one night.', false, 'Long stay', 15, true),
  ('e34a2f35-2876-58e5-aa4b-727ce4ce9df2', 'shinjuku-sky-hotel', '9c5dfe4d-f537-5208-a823-ea67766396e5', 'Shinjuku Sky Hotel', 'Shinjuku, Tokyo', 'Nishi-Shinjuku, Shinjuku City, Tokyo 160-0023, Japan', 'hotel', 4, 8.9, 1689, 341, 'Design-led hotel with city views, steps from Shinjuku Station.', 'Minimalist rooms with sweeping city views make Shinjuku Sky Hotel a calm retreat in Tokyo''s busiest district. The station is a five-minute walk, the bar overlooks the neon skyline and the onsen-style spa is perfect after a long day exploring.', array['Onsen-style baths', 'Sky bar', 'Coin laundry', 'Multilingual staff']::text[], '15:00', '11:00', 'Free cancellation up to 7 days before check-in. 50% of the stay is charged after that.', false, null, null, true)
